NGNhZC05NzhlLTlmZjlhY2Q3MDIyZiJ9XX0=
$payload$,
        '\s',
        '',
        'g'
      ),
      'base64'
    ),
    'UTF8'
  )::jsonb;
  expected_target_user_id constant uuid := 'e1c2ab6d-4a14-4c39-87bd-9cac21269a2b';
  matching_users integer;
  target_user_id uuid;
begin
  if jsonb_array_length(legacy_payload -> 'content_items') <> 4
     or jsonb_array_length(legacy_payload -> 'content_assets') <> 4
     or jsonb_array_length(legacy_payload -> 'content_subjects') <> 4 then
    raise exception 'legacy_content_payload_count_mismatch';
  end if;

  select count(*)
  into matching_users
  from public.auth_users
  where id = expected_target_user_id
    and md5(lower(email)) = 'b2f1c60e285a2ab03245be825d88473d';

  if matching_users <> 1 then
    raise exception 'legacy_administrator_account_not_found';
  end if;

  target_user_id := expected_target_user_id;

  -- The matching address was confirmed in the source Auth system before export.
  update public.auth_users
  set email_verified = true
  where id = target_user_id
    and email_verified = false;

  insert into public.user_roles (user_id, role, assigned_by)
  values (target_user_id, 'administrator', target_user_id)
  on conflict (user_id, role) do nothing;

  insert into public.content_items (
    id, kind, slug, title, summary, topic, status, content,
    estimated_minutes, is_featured, version, author_user_id,
    reviewed_by, reviewed_at, published_by, published_at, created_at, updated_at
  )
  select
    source.id,
    source.kind::public.content_kind,
    source.slug,
    source.title,
    source.summary,
    source.topic,
    source.status::public.course_status,
    source.content,
    source.estimated_minutes,
    source.is_featured,
    source.version,
    target_user_id,
    case when source.reviewed_by is null then null else target_user_id end,
    source.reviewed_at,
    case when source.published_by is null then null else target_user_id end,
    source.published_at,
    source.created_at,
    source.updated_at
  from jsonb_to_recordset(legacy_payload -> 'content_items') as source (
    id uuid,
    kind text,
    slug text,
    title text,
    summary text,
    topic text,
    status text,
    content jsonb,
    estimated_minutes integer,
    is_featured boolean,
    version integer,
    author_user_id uuid,
    reviewed_by uuid,
    reviewed_at timestamptz,
    published_by uuid,
    published_at timestamptz,
    created_at timestamptz,
    updated_at timestamptz
  )
  on conflict (id) do nothing;

  insert into public.content_assets (
    id, content_item_id, owner_user_id, kind, storage_bucket, storage_path,
    original_file_name, mime_type, size_bytes, status, finalized_at, created_at
  )
  select
    source.id,
    source.content_item_id,
    target_user_id,
    source.kind::public.content_asset_kind,
    source.storage_bucket,
    source.storage_path,
    source.original_file_name,
    source.mime_type,
    source.size_bytes,
    source.status::public.content_asset_status,
    source.finalized_at,
    source.created_at
  from jsonb_to_recordset(legacy_payload -> 'content_assets') as source (
    id uuid,
    content_item_id uuid,
    owner_user_id uuid,
    kind text,
    storage_bucket text,
    storage_path text,
    original_file_name text,
    mime_type text,
    size_bytes bigint,
    status text,
    finalized_at timestamptz,
    created_at timestamptz
  )
  on conflict (id) do nothing;

  insert into public.content_subjects (content_item_id, subject_id, created_at)
  select source.content_item_id, subject.id, source.created_at
  from jsonb_to_recordset(legacy_payload -> 'content_subjects') as source (
    content_item_id uuid,
    subject_slug text,
    created_at timestamptz
  )
  join public.subjects subject on subject.slug = source.subject_slug
  on conflict (content_item_id, subject_id) do nothing;

  if (
    select count(*)
    from public.content_items
    where id in (
      select source.id
      from jsonb_to_recordset(legacy_payload -> 'content_items') as source (id uuid)
    )
  ) <> 4 then
    raise exception 'legacy_content_restore_incomplete';
  end if;

  if (
    select count(*)
    from public.content_assets
    where id in (
      select source.id
      from jsonb_to_recordset(legacy_payload -> 'content_assets') as source (id uuid)
    )
  ) <> 4 then
    raise exception 'legacy_asset_restore_incomplete';
  end if;

  if (
    select count(*)
    from jsonb_to_recordset(legacy_payload -> 'content_subjects') as source (
      content_item_id uuid,
      subject_slug text
    )
    join public.subjects subject on subject.slug = source.subject_slug
    join public.content_subjects content_subject
      on content_subject.content_item_id = source.content_item_id
     and content_subject.subject_id = subject.id
  ) <> 4 then
    raise exception 'legacy_subject_links_restore_incomplete';
  end if;

  insert into public.audit_log (actor_user_id, action, target_type, target_id, metadata)
  select
    target_user_id,
    'legacy_supabase_content_restored',
    'system',
    null,
    jsonb_build_object(
      'assets', 4,
      'contentItems', 4,
      'payloadChecksum', '71969713a7f75335a5d2d775c442c2d5',
      'subjectLinks', 4
    )
  where not exists (
    select 1
    from public.audit_log
    where action = 'legacy_supabase_content_restored'
      and metadata ->> 'payloadChecksum' = '71969713a7f75335a5d2d775c442c2d5'
  );
end
$migration$;
